1	export type Cell = [number, number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighbor = (cell: Cell, other: Cell): boolean =>
7	  !isSameCell(cell, other) &&
8	  Math.abs(cell[0] - other[0]) <= 1 &&
9	  Math.abs(cell[1] - other[1]) <= 1;
10	
11	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((other) => isNeighbor(cell, other)).length;
13	
14	export function nextGeneration(liveCells: Cell[]): Cell[] {
15	  return liveCells.filter((cell) => {
16	    const neighborCount = countLiveNeighbors(cell, liveCells);
17	    return neighborCount === 2 || neighborCount === 3;
18	  });
19	}
